const getSRGBComponent = ({
  a,
  r,
  g,
  b,
}: {
  a: number;
  r: number;
  g: number;
  b: number;
}): SRGBColor["components"] => {
  return {
    alpha: a.toFixed(4).toString(),
    red: (r / 255).toFixed(4).toString(),
    green: (g / 255).toFixed(4).toString(),
    blue: (b / 255).toFixed(4).toString(),
  };
};

